def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    if start > finish:
        return 0
    if not s or any(ch not in "0123456789" for ch in s):
        raise ValueError("s must be a nonempty decimal string")
    if not 1 <= limit <= 9:
        raise ValueError("limit must be between 1 and 9")
    if any(int(ch) > limit for ch in s):
        return 0
    suffix = int(s)
    scale = 10 ** len(s)
    radix = limit + 1
    def count_up_to(bound: int) -> int:
        if bound <= 0 or bound < suffix:
            return 0
        maximum_prefix = (bound - suffix) // scale
        digits = str(maximum_prefix)
        place_count = radix ** (len(digits) - 1)
        total = 0
        for ch in digits:
            digit = int(ch)
            total += min(digit, radix) * place_count
            if digit > limit:
                break
            place_count //= radix
        else:
            total += 1
        if s[0] == "0":
            total -= 1
        return total
    return count_up_to(finish) - count_up_to(start - 1)

def count_valid_colorings(n: int, m: int) -> int:
    modulus = 998244353
    choices = m - 1
    correction = choices if n % 2 == 0 else -choices
    return (pow(choices, n, modulus) + correction) % modulus

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    prefix = ((0, 0, 0, 0, 0), (0, 2, 3, 3, 4), (0, 3, 6, 7, 8))
    def area_to(x: int, y: int) -> int:
        full_x, remainder_x = divmod(x, 4)
        full_y, remainder_y = divmod(y, 2)
        return (8 * full_x * full_y
                + full_y * prefix[2][remainder_x]
                + full_x * prefix[remainder_y][4]
                + prefix[remainder_y][remainder_x])
    return area_to(C, D) - area_to(A, D) - area_to(C, B) + area_to(A, B)

def kth_smallest_amount(coins: List[int], k: int) -> int:
    if k < 1:
        raise ValueError("k must be positive")
    denominations = sorted(set(coins))
    if not denominations or denominations[0] <= 0:
        raise ValueError("coins must contain positive denominations")
    essential = []
    for coin in denominations:
        if all(coin % smaller != 0 for smaller in essential):
            essential.append(coin)
    if len(essential) == 1:
        return essential[0] * k
    upper = essential[0] * k
    coefficients = {}
    for coin in essential:
        additions = {coin: 1} if coin <= upper else {}
        for previous_lcm, coefficient in coefficients.items():
            combined = lcm(previous_lcm, coin)
            if combined <= upper:
                additions[combined] = additions.get(combined, 0) - coefficient
        for multiple, coefficient in additions.items():
            updated = coefficients.get(multiple, 0) + coefficient
            if updated:
                coefficients[multiple] = updated
            else:
                coefficients.pop(multiple, None)
    terms = tuple(coefficients.items())
    def count_at_most(amount: int) -> int:
        return sum(coefficient * (amount // multiple) for multiple, coefficient in terms)
    lower = essential[0]
    while lower < upper:
        middle = (lower + upper) // 2
        if count_at_most(middle) >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower

def min_absolute_difference(nums: List[int], k: int) -> int:
    if not nums:
        raise ValueError("nums must be nonempty")
    best = abs(nums[0] - k)
    endings = set()
    for number in nums:
        endings = {number} | {value | number for value in endings}
        for value in endings:
            difference = abs(value - k)
            if difference == 0:
                return 0
            if difference < best:
                best = difference
    return best

def count_beautiful_integers(low: int, high: int, k: int) -> int:
    if k <= 0:
        raise ValueError("k must be positive")
    if low > high:
        return 0
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        length = len(digits)
        @cache
        def visit(position: int, remainder: int, balance: int, started: bool, tight: bool) -> int:
            remaining = length - position
            if started and (abs(balance) > remaining or (balance + remaining) % 2):
                return 0
            if position == length:
                return int(started and remainder == 0 and balance == 0)
            ceiling = digits[position] if tight else 9
            total = 0
            for digit in range(ceiling + 1):
                next_tight = tight and digit == digits[position]
                if not started and digit == 0:
                    total += visit(position + 1, 0, 0, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    total += visit(position + 1, (remainder * 10 + digit) % k,
                                   next_balance, True, next_tight)
            return total
        return visit(0, 0, 0, False, True)
    return count_up_to(high) - count_up_to(low - 1)

